#!/usr/bin/env bash
# Droit à l'image d'un mineur — la date de naissance reste facultative pour le parent.
# - Le parent peut confirmer, corriger ou donner la date ; laissée vide, la fiche garde la sienne (s'il y en a
#   une) et le passage à 18 ans ne sera pas automatique ;
# - « Je valide l'autorisation » ne dépend plus que de la case « représentant légal », et la page dit ce qui
#   manque ;
# - textes, doc, guide admin, visite guidée, e2e. Pas de migration.
# Prérequis : apply-instructeurs-cours-sans-depot.sh.
# Usage (racine du repo) : bash apply-parent-date-facultative.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/image-consent/GuardianConsentPage.tsx" 2>/dev/null | grep -qF "Pour valider, cochez la case"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "setTaughtCourses" "packages/backend/src/modules/users/router.ts" 2>/dev/null || { echo "lancez d'abord apply-instructeurs-cours-sans-depot.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/droit-image-d-un-mineur.mdx" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/image-consent/GuardianConsentPage.tsx" "apps/web/src/features/image-consent/OnlineConsentForm.tsx" "apps/web/src/features/tours/definitions/admin.users.droit-image-mineur.ts" "e2e/droit-a-l-image-parent-pages.spec.ts" "e2e/droit-a-l-image-parent.spec.ts" "packages/backend/src/email/templates/imageConsentGuardian.ts" "packages/backend/src/modules/imageConsent/imageConsentGuardian.service.ts" "packages/backend/src/modules/imageConsent/router.ts")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Pour valider, cochez la case" "apps/web/src/features/image-consent/GuardianConsentPage.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


